export interface Page {
  slug: string;
  title: string;
  date?: string;
  tags: string[];
  contentHtml: string;
  sourcePath: string;
  outputPath: string;
}

export interface BuildOptions {
  content: string;
  output: string;
}

import matter from 'gray-matter';

export interface Frontmatter {
  title?: string;
  date?: string;
  tags?: string[] | string;
}

const FRONTMATTER_RE = /^\uFEFF?---[ \t]*\r?\n([\s\S]*?)\r?\n---[ \t]*(\r?\n|$)/;

export interface ParsedMarkdown {
  data: Frontmatter;
  body: string;
}

/**
 * Strips the leading YAML frontmatter block (delimited by `---`) using a
 * regex, then parses the YAML with gray-matter. Stripping manually before
 * handing the body to `marked` is required: otherwise `marked` renders the
 * `---` delimiter block as literal HTML text.
 */
export function parseFrontmatter(raw: string): ParsedMarkdown {
  const match = FRONTMATTER_RE.exec(raw);
  if (!match) {
    return { data: {}, body: raw };
  }

  const yaml = match[1];
  const body = raw.slice(match[0].length);

  const parsed = matter(`---\n${yaml}\n---\n`);
  return { data: (parsed.data ?? {}) as Frontmatter, body };
}

export function normalizeTags(tags: Frontmatter['tags']): string[] {
  if (tags == null) {
    return [];
  }
  if (Array.isArray(tags)) {
    return tags.map((t) => String(t).trim()).filter(Boolean);
  }
  if (typeof tags === 'string') {
    return tags
      .split(',')
      .map((t) => t.trim())
      .filter(Boolean);
  }
  return [];
}

import { marked } from 'marked';

export async function markdownToHtml(markdown: string): Promise<string> {
  const html = await marked.parse(markdown);
  return (html ?? '').trim();
}

import type { Page } from './types';

function escapeHtml(value: string): string {
  return value
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function layout(title: string, body: string): string {
  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${escapeHtml(title)}</title>
  <style>
    body { font-family: system-ui, sans-serif; max-width: 48rem; margin: 0 auto; padding: 2rem 1rem; line-height: 1.6; }
    a { color: #2563eb; }
    .tags span { background: #e5e7eb; border-radius: 9999px; padding: 0.15rem 0.6rem; font-size: 0.8rem; margin-right: 0.35rem; }
    .meta { color: #6b7280; font-size: 0.9rem; }
  </style>
</head>
<body>
  <p><a href="index.html">&larr; All pages</a></p>
${body}
</body>
</html>
`;
}

export function renderPage(page: Page): string {
  const metaParts: string[] = [];
  if (page.date) {
    metaParts.push(escapeHtml(page.date));
  }
  if (page.tags.length > 0) {
    metaParts.push(
      `<span class="tags">${page.tags
        .map((t) => `<span>${escapeHtml(t)}</span>`)
        .join('')}</span>`
    );
  }

  const body = `
  <article>
    <h1>${escapeHtml(page.title)}</h1>
    ${metaParts.length > 0 ? `<p class="meta">${metaParts.join(' · ')}</p>` : ''}
    ${page.contentHtml}
  </article>
`;

  return layout(page.title, body);
}

export function renderIndex(pages: Page[]): string {
  const sorted = [...pages].sort((a, b) => a.title.localeCompare(b.title));

  const items = sorted
    .map((page) => {
      const metaParts: string[] = [];
      if (page.date) {
        metaParts.push(escapeHtml(page.date));
      }
      if (page.tags.length > 0) {
        metaParts.push(escapeHtml(page.tags.join(', ')));
      }
      const link = `${page.slug}.html`;
      return `    <li>
      <a href="${escapeHtml(link)}">${escapeHtml(page.title)}</a>
      ${metaParts.length > 0 ? `<span class="meta">(${metaParts.join(' · ')})</span>` : ''}
    </li>`;
    })
    .join('\n');

  const body = `
  <h1>All pages</h1>
  <ul>
${items}
  </ul>
`;

  return layout('All pages', body);
}

import { promises as fs } from 'fs';
import path from 'path';
import { parseFrontmatter, normalizeTags } from './frontmatter';
import { markdownToHtml } from './markdown';
import { renderIndex, renderPage } from './render';
import type { BuildOptions, Page } from './types';

const MARKDOWN_EXT = /\.(md|markdown)$/i;

async function findMarkdownFiles(dir: string): Promise<string[]> {
  const results: string[] = [];
  let entries;
  try {
    entries = await fs.readdir(dir, { withFileTypes: true });
  } catch {
    return results;
  }

  for (const entry of entries) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      results.push(...(await findMarkdownFiles(full)));
    } else if (entry.isFile() && MARKDOWN_EXT.test(entry.name)) {
      results.push(full);
    }
  }
  return results;
}

function slugFor(contentDir: string, filePath: string): string {
  const relative = path.relative(contentDir, filePath);
  const withoutExt = relative.replace(MARKDOWN_EXT, '');
  return withoutExt.split(path.sep).join('/');
}

function titleFor(slug: string, data: { title?: string }): string {
  if (data.title && data.title.trim()) {
    return data.title.trim();
  }
  const segments = slug.split('/').filter(Boolean);
  return segments[segments.length - 1] ?? slug;
}

export async function build(options: BuildOptions): Promise<Page[]> {
  const contentDir = path.resolve(options.content);
  const outputDir = path.resolve(options.output);

  const files = (await findMarkdownFiles(contentDir)).sort();

  const pages: Page[] = [];
  for (const file of files) {
    const raw = await fs.readFile(file, 'utf8');
    const { data, body } = parseFrontmatter(raw);
    const contentHtml = await markdownToHtml(body);
    const slug = slugFor(contentDir, file);

    pages.push({
      slug,
      title: titleFor(slug, data),
      date: data.date ? String(data.date) : undefined,
      tags: normalizeTags(data.tags),
      contentHtml,
      sourcePath: file,
      outputPath: path.join(outputDir, `${slug}.html`),
    });
  }

  await fs.mkdir(outputDir, { recursive: true });

  for (const page of pages) {
    await fs.mkdir(path.dirname(page.outputPath), { recursive: true });
    await fs.writeFile(page.outputPath, renderPage(page), 'utf8');
  }

  await fs.writeFile(path.join(outputDir, 'index.html'), renderIndex(pages), 'utf8');

  return pages;
}

#!/usr/bin/env node
import { build } from './build';

interface ParsedArgs {
  command?: string;
  content: string;
  output: string;
}

function parseArgs(argv: string[]): ParsedArgs {
  const result: ParsedArgs = { command: argv[0], content: './content', output: './dist' };
  for (let i = 1; i < argv.length; i++) {
    const arg = argv[i];
    if (arg === '--content') {
      result.content = argv[++i] ?? result.content;
    } else if (arg === '--output') {
      result.output = argv[++i] ?? result.output;
    }
  }
  return result;
}

async function main(): Promise<void> {
  const args = parseArgs(process.argv.slice(2));

  if (args.command !== 'build') {
    console.error('Usage: ssg build [--content <dir>] [--output <dir>]');
    process.exit(1);
  }

  const pages = await build({ content: args.content, output: args.output });
  console.log(`Built ${pages.length} page(s) into ${args.output}.`);
}

main().catch((err) => {
  console.error(err instanceof Error ? err.message : err);
  process.exit(1);
});

export { build } from './build';
export { parseFrontmatter, normalizeTags } from './frontmatter';
export { markdownToHtml } from './markdown';
export { renderIndex, renderPage } from './render';
export type { Frontmatter, ParsedMarkdown } from './frontmatter';
export type { BuildOptions, Page } from './types';

import { promises as fs } from 'fs';
import os from 'os';
import path from 'path';
import {
  build,
  parseFrontmatter,
  normalizeTags,
  markdownToHtml,
} from '../src';

async function makeTempDir(): Promise<string> {
  return fs.mkdtemp(path.join(os.tmpdir(), 'ssg-'));
}

describe('parseFrontmatter', () => {
  it('strips the --- frontmatter block and parses YAML', () => {
    const raw = `---
title: Hello World
date: 2024-01-01
tags:
  - typescript
  - ssg
---
# Body
This is the body.`;
    const { data, body } = parseFrontmatter(raw);

    expect(data.title).toBe('Hello World');
    expect(data.date).toBe('2024-01-01');
    expect(data.tags).toEqual(['typescript', 'ssg']);
    expect(body).not.toContain('---');
    expect(body).toContain('# Body');
  });

  it('returns the raw body when there is no frontmatter', () => {
    const raw = '# Just a heading';
    const { data, body } = parseFrontmatter(raw);
    expect(data).toEqual({});
    expect(body).toBe(raw);
  });
});

describe('normalizeTags', () => {
  it('handles arrays', () => {
    expect(normalizeTags(['a', 'b'])).toEqual(['a', 'b']);
  });

  it('handles comma-separated strings', () => {
    expect(normalizeTags('a, b, c')).toEqual(['a', 'b', 'c']);
  });

  it('handles undefined', () => {
    expect(normalizeTags(undefined)).toEqual([]);
  });
});

describe('markdownToHtml', () => {
  it('converts markdown to HTML', async () => {
    const html = await markdownToHtml('# Hello');
    expect(html).toContain('<h1>Hello</h1>');
  });
});

describe('build', () => {
  it('generates page files and an index listing all pages', async () => {
    const contentDir = await makeTempDir();
    const outputDir = await makeTempDir();

    await fs.writeFile(
      path.join(contentDir, 'hello.md'),
      `---
title: Hello
date: 2024-01-01
tags: [greeting]
---
# Welcome
This is a **test**.`
    );
    await fs.writeFile(
      path.join(contentDir, 'about.md'),
      `---
title: About
date: 2024-02-02
tags:
  - info
  - meta
---
## About us
Some text.`
    );

    const pages = await build({ content: contentDir, output: outputDir });

    expect(pages).toHaveLength(2);

    const helloHtml = await fs.readFile(path.join(outputDir, 'hello.html'), 'utf8');
    expect(helloHtml).toContain('<title>Hello</title>');
    expect(helloHtml).toContain('<h1>Hello</h1>');
    expect(helloHtml).toContain('<h1>Welcome</h1>');
    expect(helloHtml).not.toContain('---');

    const aboutHtml = await fs.readFile(path.join(outputDir, 'about.html'), 'utf8');
    expect(aboutHtml).toContain('<title>About</title>');
    expect(aboutHtml).toContain('<h2>About us</h2>');

    const indexHtml = await fs.readFile(path.join(outputDir, 'index.html'), 'utf8');
    expect(indexHtml).toContain('href="hello.html"');
    expect(indexHtml).toContain('href="about.html"');
    expect(indexHtml).toContain('Hello');
    expect(indexHtml).toContain('About');
  });

  it('handles nested directories and derives slugs', async () => {
    const contentDir = await makeTempDir();
    const outputDir = await makeTempDir();

    await fs.mkdir(path.join(contentDir, 'posts'), { recursive: true });
    await fs.writeFile(
      path.join(contentDir, 'posts', 'first.md'),
      '---\ntitle: First Post\n---\n# First'
    );

    const pages = await build({ content: contentDir, output: outputDir });
    expect(pages).toHaveLength(1);
    expect(pages[0].slug).toBe('posts/first');

    const pageHtml = await fs.readFile(
      path.join(outputDir, 'posts', 'first.html'),
      'utf8'
    );
    expect(pageHtml).toContain('<title>First Post</title>');
  });

  it('uses the slug as a fallback title when frontmatter omits title', async () => {
    const contentDir = await makeTempDir();
    const outputDir = await makeTempDir();

    await fs.writeFile(path.join(contentDir, 'no-title.md'), '# Body only');

    const pages = await build({ content: contentDir, output: outputDir });
    expect(pages[0].title).toBe('no-title');
  });
});

